import genesis as gs

def main():
    gs.init()

    scene = gs.Scene(
        viewer_options=gs.options.ViewerOptions(
            camera_pos=(3.0, 3.0, 2.0),
            camera_lookat=(0.0, 0.0, 0.5),
        ),
    )

    # Large static box
    scene.add_entity(
        gs.morphs.Box(
            size=(2.0, 2.0, 0.5),
            pos=(0.0, 0.0, 0.25),
            static=True,
        ),
    )

    # Small dynamic sphere
    scene.add_entity(
        gs.morphs.Sphere(
            radius=0.1,
            pos=(0.0, 0.0, 2.0),
        ),
        material=gs.materials.Rigid(
            rho=1000.0,
        ),
    )

    scene.build()

    for _ in range(500):
        scene.step()

if __name__ == "__main__":
    main()
